package com.hrflow.controller; import com.hrflow.entity.Department;import com.hrflow.repository.DepartmentRepository;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*; @RestController @RequestMapping("/api/departments") @RequiredArgsConstructor public class DepartmentController{final DepartmentRepository r;@GetMapping public List<Department> all(){return r.findAll();}@GetMapping("/{id}")public Department get(@PathVariable Long id){return r.findById(id).orElseThrow();}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','HR')")public Department create(@RequestBody Department x){return r.save(x);}@PutMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','HR')")public Department update(@PathVariable Long id,@RequestBody Department x){x.setId(id);return r.save(x);}@DeleteMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")public void delete(@PathVariable Long id){r.deleteById(id);}}
